import { describe, it } from 'node:test';
import assert from 'node:assert';
import { createInvoice, addLine, removeLine, issueInvoice, lineTotal, lineDiscount, invoiceTotals } from '../src/invoices.js';

describe('createInvoice', () => {
  it('creates a draft invoice with valid lines', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2 }],
    });
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value.status, 'draft');
    assert.strictEqual(result.value.lines.length, 1);
  });

  it('rejects missing customer', () => {
    const result = createInvoice({
      customerId: 'unknown',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2 }],
    });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'CUSTOMER_NOT_FOUND');
  });

  it('rejects invalid date format', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: 'not-a-date',
      lines: [{ sku: 'widget', qty: 2 }],
    });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'DATE_INVALID');
  });

  it('rejects invalid date (Feb 30)', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-02-30',
      lines: [{ sku: 'widget', qty: 2 }],
    });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'DATE_INVALID');
  });

  it('rejects empty lines array', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [],
    });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'NO_LINES');
  });

  it('rejects invalid quantity', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 0 }],
    });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'QTY_INVALID');
  });

  it('rejects unknown SKU', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'unknown-sku', qty: 2 }],
    });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'UNKNOWN_SKU');
  });

  it('accepts valid discount (0)', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2, discountPercent: 0 }],
    });
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value.lines[0].discountPercent, 0);
  });

  it('accepts valid discount (50)', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2, discountPercent: 50 }],
    });
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value.lines[0].discountPercent, 50);
  });

  it('accepts valid discount (100)', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2, discountPercent: 100 }],
    });
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value.lines[0].discountPercent, 100);
  });

  it('accepts decimal discount (12.5)', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2, discountPercent: 12.5 }],
    });
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value.lines[0].discountPercent, 12.5);
  });

  it('rejects discount > 100', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2, discountPercent: 101 }],
    });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'DISCOUNT_INVALID');
  });

  it('rejects negative discount', () => {
    const result = createInvoice({
      customerId: 'cust1',
      issueDate: '2026-01-15',
      lines: [{ sku: 'widget', qty: 2, discountPercent: -1 }],
