        { sku: 'gadget', name: 'Gadget', qty: 1, unitPrice: 500, vatRate: 0.19, discountPercent: 0 },
      ],
    };
    const result = removeLine(invoice, 'widget');
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value.lines.length, 1);
    assert.strictEqual(result.value.lines[0].sku, 'gadget');
  });

  it('rejects removeLine on non-draft invoice', () => {
    const invoice = {
      customerId: 'cust1',
      issueDate: '2026-01-15',
      status: 'issued',
      number: 'INV-001',
      lines: [{ sku: 'widget', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 0.19, discountPercent: 0 }],
    };
    const result = removeLine(invoice, 'widget');
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'NOT_DRAFT');
  });

  it('rejects removeLine when line not found', () => {
    const invoice = {
      customerId: 'cust1',
      issueDate: '2026-01-15',
      status: 'draft',
      lines: [{ sku: 'widget', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 0.19, discountPercent: 0 }],
    };
    const result = removeLine(invoice, 'unknown');
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'LINE_NOT_FOUND');
  });

  it('rejects removeLine when it would leave no lines', () => {
    const invoice = {
      customerId: 'cust1',
      issueDate: '2026-01-15',
      status: 'draft',
      lines: [{ sku: 'widget', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 0.19, discountPercent: 0 }],
    };
    const result = removeLine(invoice, 'widget');
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'NO_LINES');
  });
});

describe('issueInvoice', () => {
  it('issues a draft invoice', () => {
    const invoice = {
      customerId: 'cust1',
      issueDate: '2026-01-15',
      status: 'draft',
      lines: [{ sku: 'widget', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 0.19, discountPercent: 0 }],
    };
    const result = issueInvoice(invoice, []);
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value.status, 'issued');
    assert.strictEqual(typeof result.value.number, 'string');
  });

  it('rejects issueInvoice on non-draft invoice', () => {
    const invoice = {
      customerId: 'cust1',
      issueDate: '2026-01-15',
      status: 'issued',
      number: 'INV-001',
      lines: [{ sku: 'widget', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 0.19, discountPercent: 0 }],
    };
    const result = issueInvoice(invoice, []);
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'NOT_DRAFT');
  });
});

